//! End-to-end proofs of the model zoo.
//!
//! Checked-in models run on every CI run: the synthetic op gauntlet and the
//! tiny random-init stand-ins generated by `scripts/gen_tiny_models.py` with
//! the production architectures and the same ONNX exporter as the real
//! downloads. Each tiny test asserts that the importer rewrites the real
//! model relies on actually fired, so it is structurally the same proof,
//! only smaller. The real downloads are `#[ignore]`d and run in the heavy
//! CI job.

use ark_bn254::Bn254;
use atlas_onnx_import::fixtures::{standard_bindings, synth_inputs, GOLDEN_SEED};
use atlas_onnx_import::ImportedModel;
use atlas_trace::Tensor;
use joltworks::field::bn254::Fr;
use joltworks::poly::commitment::{dory::DoryScheme, hyperkzg::HyperKZG};

use super::{prove_verify_roundtrip, RoundtripOptions};
use crate::loader::{load_imported, RunArgs};

pub(super) fn zoo(name: &str, seq_len: usize) -> ImportedModel {
    load_imported(
        &format!("../models/{name}/network.onnx"),
        &RunArgs::new(standard_bindings(seq_len)),
    )
}

/// Every named importer pass must have rewritten at least once.
fn assert_passes_fired(imported: &ImportedModel, passes: &[&str]) {
    for pass in passes {
        let fired = imported
            .pass_reports
            .iter()
            .any(|r| r.name == *pass && r.rewrites > 0);
        assert!(
            fired,
            "importer pass `{pass}` did not fire; the fixture no longer exercises it. pass log: {:?}",
            imported
                .pass_reports
                .iter()
                .filter(|r| r.rewrites > 0)
                .map(|r| (r.name, r.rewrites))
                .collect::<Vec<_>>()
        );
    }
}

fn einsum_equations(imported: &ImportedModel) -> Vec<String> {
    imported
        .model
        .graph()
        .nodes
        .iter()
        .filter_map(|n| match &n.op {
            atlas_trace::Op::Einsum(e) => Some(e.equation.to_string()),
            _ => None,
        })
        .collect()
}

/// The gauntlet's golden inputs with one position masked out, so the
/// attention mask path is live.
pub(super) fn op_gauntlet_inputs(imported: &ImportedModel) -> Vec<Tensor<i32>> {
    let mut inputs = synth_inputs(imported, GOLDEN_SEED);
    let mask = imported
        .input_descriptors
        .iter()
        .position(|d| d.name.contains("mask"))
        .expect("gauntlet has an attention mask");
    let dims = inputs[mask].dims().to_vec();
    let mut data = inputs[mask].data().to_vec();
    *data.last_mut().unwrap() = 0;
    inputs[mask] = Tensor::from_slice(&data, &dims).unwrap();
    inputs
}

// ── checked-in zoo ───────────────────────────────────────────────────────

/// One small synthetic model covering the lowerable op surface: embedding
/// gather, decomposed LayerNorm, masked attention (Where/IsNaN), both GELU
/// forms, RMSNorm, Split/Concat/Expand, every sum-axis shape, trig/sigmoid,
/// Neg/Square, and a Cast descale round trip (`scripts/gen_test_models.py`).
#[test]
fn op_gauntlet() {
    let imported = zoo("op_gauntlet", 16);
    let inputs = op_gauntlet_inputs(&imported);
    prove_verify_roundtrip::<HyperKZG<Bn254>>(imported.model, &inputs, RoundtripOptions::default());
}

/// GPT-2 architecture (2 layers, 48 hidden, 3 heads, vocab 1000) exported
/// with past-KV inputs like the real model: native LayerNormalization,
/// Gemm, fused-QKV Split, tanh GELU, IsNaN/Where mask, KV-cache elision.
#[test]
fn gpt2_tiny_dory() {
    let imported = zoo("gpt2-tiny", 16);
    assert_passes_fired(
        &imported,
        &[
            "elide",
            "norm_fusion",
            "matmul_gemm_to_einsum",
            "slice_through_projection",
            "split_to_slices",
        ],
    );
    let inputs = synth_inputs(&imported, GOLDEN_SEED);
    prove_verify_roundtrip::<DoryScheme>(imported.model, &inputs, RoundtripOptions::default());
}

/// Qwen2 architecture (2 layers, 56 hidden, 7 query heads over 1 KV head):
/// GQA ratio 7 → `repeat_to_gather` + the `amk,ank->amn` outer-product
/// einsum (the path PR #382 broke with no test), RoPE Cos/Sin over scaled
/// position ids, RMSNorm, SiLU, tied embeddings.
#[test]
fn qwen2_tiny_dory() {
    let imported = zoo("qwen2-tiny", 16);
    assert_passes_fired(
        &imported,
        &[
            "repeat_to_gather",
            "norm_fusion",
            "div_rewrites",
            "expand_to_broadcast",
        ],
    );
    assert!(
        einsum_equations(&imported)
            .iter()
            .any(|e| e == "amk,ank->amn"),
        "qwen2-tiny must lower the GQA outer-product einsum"
    );
    let inputs = synth_inputs(&imported, GOLDEN_SEED);
    prove_verify_roundtrip::<DoryScheme>(imported.model, &inputs, RoundtripOptions::default());
}

/// The same model under HyperKZG.
#[test]
fn qwen2_tiny_hyperkzg() {
    let imported = zoo("qwen2-tiny", 16);
    let inputs = synth_inputs(&imported, GOLDEN_SEED);
    prove_verify_roundtrip::<HyperKZG<Bn254>>(imported.model, &inputs, RoundtripOptions::default());
}

/// Same model at a non-power-of-two sequence length: would pad the sequence
/// axis through attention, RoPE and the causal mask.
#[test]
#[ignore = "known gap: the importer rejects a non-power-of-two sequence length for the Qwen2 \
            graph (`Slice(axis 3, 0..12): padding failed: slice extent 12 is not a power of two`); \
            needs the unit-axis squeeze / padded-slice coherence work in atlas-onnx-import"]
fn known_gap_qwen2_tiny_seq12() {
    let imported = zoo("qwen2-tiny", 12);
    let inputs = synth_inputs(&imported, GOLDEN_SEED);
    prove_verify_roundtrip::<HyperKZG<Bn254>>(imported.model, &inputs, RoundtripOptions::default());
}

/// BERT architecture (2 layers, 48 hidden, 3 heads) at opset 14: Erf GELU,
/// decomposed LayerNorm with eps 1e-12 (`rsqrt_eps_floor`), token_type gather.
#[test]
fn bge_tiny() {
    let imported = zoo("bge-tiny", 16);
    assert_passes_fired(
        &imported,
        &["norm_fusion", "rsqrt_eps_floor", "matmul_gemm_to_einsum"],
    );
    let inputs = synth_inputs(&imported, GOLDEN_SEED);
    prove_verify_roundtrip::<HyperKZG<Bn254>>(imported.model, &inputs, RoundtripOptions::default());
}

