// ── transcript binding (issue #230) ──────────────────────────────────────

/// Changing one input element must change the first derived challenge: the
/// inputs are absorbed into the transcript before any challenge, which is
/// what removes the adaptive forge's precondition (input-independent,
/// prover-known opening points).
#[test]
fn input_binding_changes_transcript() {
    use crate::onnx_proof::append_inputs_to_transcript;
    use atlas_trace::trace::ModelExecutionIO;
    use joltworks::transcripts::{Blake2bProver, ProvingTranscript, Transcript};

    let io = |vals: &[i32]| ModelExecutionIO {
        inputs: vec![Tensor::from_slice(vals, &[vals.len()]).unwrap()],
        outputs: vec![],
        input_indices: vec![0],
        output_indices: vec![],
    };
    let challenge_for = |vals: &[i32]| -> Fr {
        let mut t = Blake2bProver::new(b"ONNXProof");
        append_inputs_to_transcript(&mut t, &io(vals));
        t.challenge_scalar::<Fr>()
    };

    let base = [3, 1, 4, 1, 5, 9, 2, 6];
    let mut flipped = base;
    flipped[0] = -flipped[0];
    assert_eq!(challenge_for(&base), challenge_for(&base));
    assert_ne!(
        challenge_for(&base),
        challenge_for(&flipped),
        "changing an input must change the derived challenge (issue #230)"
    );
}
